test('never-resolving logout is bounded honestly and cannot restart boot',async()=>{const h=harness({signOut:()=>new Promise(()=>{})});h.eval('bootLogout()');await h.timeout();assert.equal(h.state().phase,'logout-timeout');assert.match(h.panel().innerHTML,/saída ainda não foi confirmada/);h.start();assert.equal(h.calls.session,0);h.click();h.click();assert.equal(h.calls.reload,1);assert.equal(h.calls.logout,1);});
