test('successful product preserves exact default flow dates and presets',async()=>{const h=harness();await h.start();assert.equal(h.state().phase,'ready');assert.equal(h.panel().hidden,true);assert.equal(h.A.attributes['aria-hidden'],undefined);assert.equal(h.N.classList.contains('hidden'),false);assert.equal(h.LO.classList.contains('hidden'),false);assert.equal(h.calls.render,1);assert.equal(h.calls.nav,1);assert.deepEqual(h.calls.flow,[['2026-10-16','2026-11-14']]);assert.equal(h.state().FLOWPRESET,'Próximos 30 dias');assert.equal(h.state().FLOWFORCEZERO,false);assert.equal(h.timers.size,0);});
(async()=>{let failed=0;const result=[];for(const [name,fn] of tests){try{await fn();console.log('PASS '+name);result.push({name,status:'pass'});}catch(error){failed++;console.error('FAIL '+name+'\n'+error.stack);result.push({name,status:'fail',error:error.message});}}const summary={mode:'synthetic-node-vm-no-network-no-browser',passed:tests.length-failed,failed,tests:result};fs.writeFileSync('qa/v280-boot-contract-results.json',JSON.stringify(summary,null,2)+'\n');console.log(JSON.stringify({passed:summary.passed,failed}));process.exitCode=failed?1:0;})();
